.comparison-table{
    width:100%;
    border:1px solid rgba(255,255,255,.08);
    border-radius:18px;
    overflow:hidden;
    background:#111;
}

.comparison-header,
.comparison-row{
    display:grid;
    grid-template-columns:2.2fr 1fr 1fr 1fr;
    align-items:center;
}

.comparison-header{
    background:#F68C11;
    color:#fff;
    font-weight:700;
}

.comparison-header div,
.comparison-row div{
    padding:18px;
    border-bottom:1px solid rgba(255,255,255,.08);
}

.comparison-row{
    color:#fff;
    transition:.3s;
}

.comparison-row:hover{
    background:rgba(246,140,17,.08);
}

.yes{
    color:#F68C11;
    font-size:22px;
    text-align:center;
}

.title{
    font-weight:600;
}

@media(max-width:768px){

    .comparison-header{
        display:none;
    }

    .comparison-row{
        display:block;
        padding:18px;
        margin:15px;
        border:1px solid rgba(255,255,255,.08);
        border-radius:16px;
        background:#181818;
    }

    .comparison-row div{
        display:flex;
        justify-content:space-between;
        border:none;
        padding:10px 0;
    }

    .comparison-row div::before{
        color:#999;
        font-weight:600;
    }

    .comparison-row div:nth-child(2)::before{
        content:"Veloce";
    }

    .comparison-row div:nth-child(3)::before{
        content:"Concessionária";
    }

    .comparison-row div:nth-child(4)::before{
        content:"Oficina comum";
    }

    .title::before{
        content:"";
    }

    .title{
        display:block !important;
        font-size:18px;
        margin-bottom:12px;
    }
}
